CREATE OR REPLACE FUNCTION public.refresh_business_profile_onboarding_status_from_integration()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE
  v_business_id uuid;
BEGIN
  IF TG_OP = 'DELETE' THEN
    v_business_id := OLD.business_id;
  ELSE
    v_business_id := NEW.business_id;
  END IF;

  PERFORM public.refresh_business_profile_onboarding_status(v_business_id);
  RETURN COALESCE(NEW, OLD);
END;
$function$

CREATE OR REPLACE FUNCTION public.claim_scheduled_job_lock(p_job_key text, p_scheduled_for timestamp with time zone, p_locked_by text DEFAULT NULL::text, p_lock_ttl_seconds integer DEFAULT 7200, p_metadata jsonb DEFAULT '{}'::jsonb)
 RETURNS TABLE(claimed boolean, lock_id uuid, reason text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare
  v_now timestamptz := now();
  v_lock public.scheduled_job_locks%rowtype;
  v_ttl interval := make_interval(secs => greatest(coalesce(p_lock_ttl_seconds, 7200), 60));
begin
  if p_job_key is null or length(trim(p_job_key)) = 0 then
    return query select false, null::uuid, 'missing_job_key';
    return;
  end if;

  insert into public.scheduled_job_locks (
    job_key,
    scheduled_for,
    locked_at,
    locked_by,
    completed_at,
    status,
    metadata,
    created_at,
    updated_at
  )
  values (
    p_job_key,
    p_scheduled_for,
    v_now,
    p_locked_by,
    null,
    'running',
    coalesce(p_metadata, '{}'::jsonb),
    v_now,
    v_now
  )
  on conflict (job_key) do nothing
  returning * into v_lock;

  if v_lock.id is not null then
    return query select true, v_lock.id, 'claimed';
    return;
  end if;

  select *
  into v_lock
  from public.scheduled_job_locks
  where job_key = p_job_key
  for update;

  if v_lock.id is null then
    return query select false, null::uuid, 'not_found';
    return;
  end if;

  if v_lock.status = 'completed' then
    return query select false, v_lock.id, 'already_completed';
    return;
  end if;

  if v_lock.status = 'running' and v_lock.locked_at > v_now - v_ttl then
    return query select false, v_lock.id, 'already_running';
    return;
  end if;

  update public.scheduled_job_locks
  set
    locked_at = v_now,
    locked_by = p_locked_by,
    completed_at = null,
    status = 'running',
    metadata = coalesce(v_lock.metadata, '{}'::jsonb) || coalesce(p_metadata, '{}'::jsonb),
    updated_at = v_now
  where id = v_lock.id
  returning * into v_lock;

  return query select true, v_lock.id, 'reclaimed';
end;
$function$

CREATE OR REPLACE FUNCTION public.handle_confirmed_auth_user_profile()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare
  first_name_text text;
  last_name_text text;
  full_name_text text;
begin
  if new.email_confirmed_at is null then
    return new;
  end if;

  first_name_text := nullif(trim(coalesce(new.raw_user_meta_data->>'first_name', '')), '');
  last_name_text := nullif(trim(coalesce(new.raw_user_meta_data->>'last_name', '')), '');
  full_name_text := nullif(
    trim(coalesce(new.raw_user_meta_data->>'full_name', concat_ws(' ', first_name_text, last_name_text))),
    ''
  );

  insert into public.user_profiles (
    id,
    email,
    role,
    first_name,
    last_name,
    full_name
  )
  values (
    new.id,
    new.email,
    'owner',
    first_name_text,
    last_name_text,
    full_name_text
  )
  on conflict (id) do update
  set
    email = excluded.email,
    first_name = coalesce(public.user_profiles.first_name, excluded.first_name),
    last_name = coalesce(public.user_profiles.last_name, excluded.last_name),
    full_name = coalesce(public.user_profiles.full_name, excluded.full_name),
    role = coalesce(public.user_profiles.role, excluded.role);

  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.gpt_messages_after_delete_trg()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
begin
  -- Only recalc if the deleted row was the newest; simplest approach is to just recalc always
  perform public.recalc_thread_last_message(old.thread_id);
  return old;
end;
$function$

