CREATE OR REPLACE FUNCTION public.sync_tax_payment_year_fields()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
begin
  if new.tax_year is null and new.year is not null then
    new.tax_year := new.year;
  elsif new.year is null and new.tax_year is not null then
    new.year := new.tax_year;
  elsif new.tax_year is distinct from new.year then
    -- Prefer canonical tax_year when both are supplied.
    new.year := new.tax_year;
  end if;

  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.prevent_completed_tax_run_mutation()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
begin
  if tg_op = 'DELETE' and old.status = 'completed' then
    raise exception
      'Completed tax calculation runs are immutable';
  end if;

  if tg_op = 'UPDATE' and old.status = 'completed' then
    raise exception
      'Completed tax calculation runs are immutable';
  end if;

  if tg_op = 'DELETE' then
    return old;
  end if;

  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.confirm_credit_card_payment_pair_atomic(p_business_id uuid, p_pair_id uuid, p_actor text DEFAULT 'user'::text, p_match_method text DEFAULT 'books_review'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_pair public.credit_card_payment_pairs;
  v_checking public.bank_transactions;
  v_card public.bank_transactions;
  v_checking_cat public.transaction_categorizations;
  v_card_cat public.transaction_categorizations;
  v_now timestamptz := now();
  v_days integer;
begin
  select * into v_pair from public.credit_card_payment_pairs
   where business_id = p_business_id and id = p_pair_id for update;
  if not found then raise exception 'cc_payment_pair_not_found'; end if;
  if v_pair.credit_card_transaction_id is null then raise exception 'cc_payment_pair_missing_opposite_leg'; end if;
  if v_pair.checking_transaction_id = v_pair.credit_card_transaction_id then raise exception 'cc_payment_pair_same_transaction'; end if;

  select * into v_checking from public.bank_transactions
   where business_id = p_business_id and id = v_pair.checking_transaction_id for update;
  select * into v_card from public.bank_transactions
   where business_id = p_business_id and id = v_pair.credit_card_transaction_id for update;
  if v_checking.id is null or v_card.id is null then raise exception 'cc_payment_pair_transaction_not_found'; end if;
  if v_checking.plaid_account_id is distinct from v_pair.checking_plaid_account_id
     or v_card.plaid_account_id is distinct from v_pair.credit_card_plaid_account_id then
    raise exception 'cc_payment_pair_account_mismatch';
  end if;
  if v_checking.pending or v_card.pending or coalesce(v_checking.is_archived, false) or coalesce(v_card.is_archived, false) then
    raise exception 'cc_payment_pair_transaction_ineligible';
  end if;
  if not ((coalesce(v_checking.signed_amount, v_checking.amount) < 0 and coalesce(v_card.signed_amount, v_card.amount) > 0)
       or (upper(coalesce(v_checking.direction, '')) = 'OUTFLOW' and upper(coalesce(v_card.direction, '')) = 'INFLOW')) then
    raise exception 'cc_payment_pair_sign_mismatch';
  end if;
  if round(abs(coalesce(v_checking.signed_amount, v_checking.amount)) * 100) <> round(abs(coalesce(v_card.signed_amount, v_card.amount)) * 100)
     or round(abs(coalesce(v_checking.signed_amount, v_checking.amount)) * 100) <> round(abs(v_pair.amount) * 100) then
    raise exception 'cc_payment_pair_amount_mismatch';
  end if;
  v_days := abs(v_checking.date - v_card.date);
  if v_days > 7 then raise exception 'cc_payment_pair_date_window_exceeded'; end if;

  select * into v_checking_cat from public.transaction_categorizations
   where business_id = p_business_id and transaction_id = v_pair.checking_transaction_id for update;
  select * into v_card_cat from public.transaction_categorizations
   where business_id = p_business_id and transaction_id = v_pair.credit_card_transaction_id for update;
  if v_checking_cat.transaction_id is null or v_card_cat.transaction_id is null then
    raise exception 'cc_payment_pair_categorization_missing';
  end if;
  if v_checking_cat.status not in ('needs_review', 'handled', 'matched') or v_card_cat.status not in ('needs_review', 'handled', 'matched') then
    raise exception 'cc_payment_pair_transaction_ineligible';
  end if;
  if v_checking_cat.qbo_txn_id is not null or v_card_cat.qbo_txn_id is not null
     or v_checking_cat.posted_at is not null or v_card_cat.posted_at is not null then
    raise exception 'cc_payment_pair_leg_already_posted';
  end if;
  if (v_checking_cat.meta->>'cc_payment_pair_id') is not null and (v_checking_cat.meta->>'cc_payment_pair_id') <> v_pair.id::text then
    raise exception 'cc_payment_pair_leg_already_consumed';
  end if;
  if (v_card_cat.meta->>'cc_payment_pair_id') is not null and (v_card_cat.meta->>'cc_payment_pair_id') <> v_pair.id::text then
    raise exception 'cc_payment_pair_leg_already_consumed';
  end if;

  if v_pair.status in ('confirmed', 'posting', 'failed', 'posted')
     and v_checking_cat.status = 'handled' and v_card_cat.status = 'handled' then
    return jsonb_build_object('ok', true, 'idempotent', true, 'pair', to_jsonb(v_pair),
      'transaction_ids', jsonb_build_array(v_pair.checking_transaction_id, v_pair.credit_card_transaction_id));
  end if;
  if v_pair.status not in ('needs_review', 'confirmed') then raise exception 'cc_payment_pair_not_confirmable'; end if;

  update public.credit_card_payment_pairs set
    status = 'confirmed', post_error = null, updated_at = v_now,
    match_evidence = coalesce(match_evidence, '{}'::jsonb) || jsonb_build_object(
      'confirmed_at', v_now, 'confirmed_by', p_actor, 'confirmation_source', p_match_method)
   where business_id = p_business_id and id = v_pair.id returning * into v_pair;

  insert into public.transaction_categorizations
    (business_id, transaction_id, status, post_after, post_error, qbo_txn_id, qbo_txn_type, posted_at,
     final_qbo_account_id, final_qbo_account_name, meta, decided_by, decided_at, updated_at)
  values
    (p_business_id, v_pair.checking_transaction_id, 'handled', null, null, null, null, null, null, null,
     coalesce(v_checking_cat.meta, '{}'::jsonb) || jsonb_build_object(
       'taxonomy_type','cc_payment','cc_payment_pair_id',v_pair.id,'cc_payment_pair_role','checking',
       'cc_payment_pair_txn_id',v_pair.credit_card_transaction_id,'cc_payment_pair_status','confirmed',
       'cc_payment_bank_qbo_account_id',v_pair.checking_qbo_account_id,
       'cc_payment_cc_qbo_account_id',v_pair.credit_card_qbo_account_id,
       'cc_payment_transfer_target_qbo_account_id',v_pair.credit_card_qbo_account_id,
       'cc_payment_pair_counterpart_amount',v_pair.amount,
       'cc_payment_pair_counterpart_date',v_pair.matched_date,
       'cc_payment_pair_confidence',v_pair.match_confidence,'cc_payment_pair_confirmed_at',v_now,
       'cc_payment_pair_confirmed_by',p_actor,'cc_payment_pair_confirmation_source',p_match_method,
       'match_type','credit_card_payment_pair','safe_to_auto_handle',false,'safe_to_auto_post',false),
     p_actor, v_now, v_now),
    (p_business_id, v_pair.credit_card_transaction_id, 'handled', null, null, null, null, null, null, null,
     coalesce(v_card_cat.meta, '{}'::jsonb) || jsonb_build_object(
       'taxonomy_type','cc_payment','cc_payment_pair_id',v_pair.id,'cc_payment_pair_role','credit_card',
       'cc_payment_pair_txn_id',v_pair.checking_transaction_id,'cc_payment_pair_status','confirmed',
       'cc_payment_bank_qbo_account_id',v_pair.checking_qbo_account_id,
       'cc_payment_cc_qbo_account_id',v_pair.credit_card_qbo_account_id,
       'cc_payment_transfer_target_qbo_account_id',v_pair.checking_qbo_account_id,
       'cc_payment_pair_counterpart_amount',-v_pair.amount,
       'cc_payment_pair_counterpart_date',v_pair.payment_date,
       'cc_payment_pair_confidence',v_pair.match_confidence,'cc_payment_pair_confirmed_at',v_now,
       'cc_payment_pair_confirmed_by',p_actor,'cc_payment_pair_confirmation_source',p_match_method,
       'match_type','credit_card_payment_pair','safe_to_auto_handle',false,'safe_to_auto_post',false),
     p_actor, v_now, v_now)
  on conflict (business_id, transaction_id) do update set
    status = excluded.status, post_after = null, post_error = null, qbo_txn_id = null, qbo_txn_type = null,
    posted_at = null, final_qbo_account_id = null, final_qbo_account_name = null,
    meta = excluded.meta, decided_by = excluded.decided_by, decided_at = excluded.decided_at, updated_at = excluded.updated_at;

  insert into public.credit_card_payment_pair_events (business_id, pair_id, transaction_id, event_type, actor, metadata)
  values
    (p_business_id, v_pair.id, v_pair.checking_transaction_id, 'confirmed', p_actor, jsonb_build_object('role','checking','method',p_match_method)),
    (p_business_id, v_pair.id, v_pair.credit_card_transaction_id, 'confirmed', p_actor, jsonb_build_object('role','credit_card','method',p_match_method));

  return jsonb_build_object('ok', true, 'idempotent', false, 'pair', to_jsonb(v_pair),
    'transaction_ids', jsonb_build_array(v_pair.checking_transaction_id, v_pair.credit_card_transaction_id));
end;
$function$

CREATE OR REPLACE FUNCTION public.acquire_posting_lock(p_business_id uuid, p_transaction_id uuid, p_now_iso timestamp with time zone, p_lock_stale_seconds integer, p_idempotency_key text)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE
  v_meta jsonb;
  v_started_at timestamptz;
  v_in_progress boolean;
  v_qbo_txn_id text;
  v_status text;
  v_existing_key text;
BEGIN
  SELECT status, qbo_txn_id, meta
    INTO v_status, v_qbo_txn_id, v_meta
  FROM public.transaction_categorizations
  WHERE business_id = p_business_id
    AND transaction_id = p_transaction_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RETURN false;
  END IF;

  IF v_status = 'posted' OR v_qbo_txn_id IS NOT NULL THEN
    RETURN false;
  END IF;

  v_in_progress := COALESCE((v_meta->>'posting_in_progress')::boolean, false);
  v_started_at := NULLIF(v_meta->>'posting_started_at','')::timestamptz;

  IF v_in_progress AND v_started_at IS NOT NULL THEN
    IF EXTRACT(EPOCH FROM (p_now_iso - v_started_at)) < p_lock_stale_seconds THEN
      RETURN false;
    END IF;
  END IF;

  v_existing_key := NULLIF(v_meta->>'post_idempotency_key','');
  IF v_existing_key IS NULL THEN
    v_existing_key := p_idempotency_key;
  END IF;

  UPDATE public.transaction_categorizations
  SET
    last_post_attempt_at = p_now_iso,
    meta = jsonb_set(
            jsonb_set(
              jsonb_set(
                COALESCE(meta, '{}'::jsonb),
                '{posting_in_progress}',
                'true'::jsonb,
                true
              ),
              '{posting_started_at}',
              to_jsonb(p_now_iso),
              true
            ),
            '{post_idempotency_key}',
            to_jsonb(v_existing_key),
            true
          )
  WHERE business_id = p_business_id
    AND transaction_id = p_transaction_id;

  RETURN true;
END;
$function$

CREATE OR REPLACE FUNCTION public.enforce_active_credit_card_payment_pair_membership()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_left uuid;
  v_right uuid;
begin
  if new.status = 'voided' or new.credit_card_transaction_id is null then
    return new;
  end if;
  v_left := least(new.checking_transaction_id, new.credit_card_transaction_id);
  v_right := greatest(new.checking_transaction_id, new.credit_card_transaction_id);
  perform pg_advisory_xact_lock(hashtextextended(new.business_id::text || ':' || v_left::text, 0));
  perform pg_advisory_xact_lock(hashtextextended(new.business_id::text || ':' || v_right::text, 0));
  if exists (
    select 1 from public.credit_card_payment_pairs p
    where p.business_id = new.business_id and p.status <> 'voided'
      and p.id is distinct from new.id
      and (
        p.checking_transaction_id in (new.checking_transaction_id, new.credit_card_transaction_id)
        or p.credit_card_transaction_id in (new.checking_transaction_id, new.credit_card_transaction_id)
      )
  ) then
    raise exception 'credit_card_payment_pair_leg_already_consumed';
  end if;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.approve_bookkeeping_transactions_atomic(p_business_id uuid, p_actor_id uuid, p_actor_type text, p_approvals jsonb, p_require_needs_review boolean DEFAULT true)
 RETURNS SETOF transaction_categorizations
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  approval jsonb;
  current_row public.transaction_categorizations%ROWTYPE;
  bank_row public.bank_transactions%ROWTYPE;
  event_key text;
  inflow_decision jsonb;
  is_credit_card_inflow boolean;
BEGIN
  IF p_actor_type NOT IN ('user','admin','system','automation') THEN RAISE EXCEPTION 'invalid_approval_actor_type' USING ERRCODE='22023'; END IF;
  IF p_actor_type IN ('user','admin') AND p_actor_id IS NULL THEN RAISE EXCEPTION 'missing_approval_actor_id' USING ERRCODE='22023'; END IF;
  IF jsonb_typeof(p_approvals) <> 'array' OR jsonb_array_length(p_approvals)=0 THEN RAISE EXCEPTION 'missing_approvals' USING ERRCODE='22023'; END IF;

  FOR approval IN SELECT value FROM jsonb_array_elements(p_approvals) LOOP
    SELECT * INTO bank_row FROM public.bank_transactions bt
      WHERE bt.business_id=p_business_id AND bt.id=(approval->>'transaction_id')::uuid AND bt.is_archived=false FOR UPDATE;
    IF bank_row.id IS NULL THEN RAISE EXCEPTION 'approval_transaction_not_found' USING ERRCODE='P0002'; END IF;

    SELECT * INTO current_row FROM public.transaction_categorizations tc
      WHERE tc.business_id=p_business_id AND tc.transaction_id=(approval->>'transaction_id')::uuid FOR UPDATE;
    event_key := approval->>'approval_idempotency_key';
    IF coalesce(event_key,'')='' THEN RAISE EXCEPTION 'missing_approval_idempotency_key' USING ERRCODE='22023'; END IF;
    IF EXISTS (SELECT 1 FROM public.bookkeeping_approval_events e WHERE e.business_id=p_business_id AND e.idempotency_key=event_key) THEN CONTINUE; END IF;
    IF p_require_needs_review AND current_row.id IS NOT NULL AND lower(coalesce(current_row.status,'needs_review')) NOT IN ('needs_review','uncategorized') THEN
      RAISE EXCEPTION 'transaction_not_needs_review' USING ERRCODE='40001';
    END IF;

    inflow_decision := approval#>'{meta,credit_card_inflow_resolution}';
    SELECT (
      (upper(coalesce(bank_row.direction,''))='INFLOW' OR coalesce(bank_row.amount,0)>0)
      AND EXISTS (
        SELECT 1 FROM public.plaid_qbo_account_mappings pam
        WHERE pam.business_id=p_business_id
          AND pam.plaid_account_id=bank_row.plaid_account_id
          AND regexp_replace(lower(coalesce(pam.qbo_account_type,'')),'[^a-z]','','g')='creditcard'
      )
    ) INTO is_credit_card_inflow;
    IF bank_row.accounting_review_required IS TRUE THEN
      IF bank_row.accounting_review_reason <> 'operator_confirmed_settlement'
         OR bank_row.pending IS TRUE
         OR bank_row.pending_resolution_state <> 'promoted_to_settled'
         OR bank_row.pending_resolution_payload->>'confirmed_at' IS NULL
         OR (is_credit_card_inflow AND (
           coalesce(inflow_decision->>'resolution_type','') NOT IN ('merchant_refund','credit_card_statement_credit')
           OR inflow_decision->>'destination_qbo_account_id' IS NULL
           OR inflow_decision->>'decided_by' IS NULL
           OR inflow_decision->>'decided_at' IS NULL
         )) THEN
        RAISE EXCEPTION 'credit_card_inflow_type_required' USING ERRCODE='22023';
      END IF;
      UPDATE public.bank_transactions SET
        accounting_review_required=false,
        accounting_review_reason=null,
        accounting_review_payload=null,
        updated_at=coalesce(nullif(approval->>'updated_at','')::timestamptz,now())
      WHERE business_id=p_business_id AND id=bank_row.id;
    END IF;

    INSERT INTO public.transaction_categorizations (
      business_id,transaction_id,status,final_qbo_account_id,final_qbo_account_name,
      final_canonical_account_key,confidence,reason,decided_by,decided_at,updated_at,
      post_after,post_error,meta
    ) VALUES (
      p_business_id,(approval->>'transaction_id')::uuid,coalesce(approval->>'status','approved'),
      approval->>'final_qbo_account_id',approval->>'final_qbo_account_name',approval->>'final_canonical_account_key',
      approval->>'confidence',approval->>'reason',p_actor_type,(approval->>'decided_at')::timestamptz,
      (approval->>'updated_at')::timestamptz,nullif(approval->>'post_after','')::timestamptz,
      approval->>'post_error',coalesce(approval->'meta','{}'::jsonb)
    ) ON CONFLICT (business_id,transaction_id) DO UPDATE SET
      status=EXCLUDED.status,final_qbo_account_id=EXCLUDED.final_qbo_account_id,
      final_qbo_account_name=EXCLUDED.final_qbo_account_name,final_canonical_account_key=EXCLUDED.final_canonical_account_key,
      confidence=EXCLUDED.confidence,reason=EXCLUDED.reason,decided_by=EXCLUDED.decided_by,
      decided_at=EXCLUDED.decided_at,updated_at=EXCLUDED.updated_at,post_after=EXCLUDED.post_after,
      post_error=EXCLUDED.post_error,meta=EXCLUDED.meta;

    INSERT INTO public.bookkeeping_approval_events (
      business_id,transaction_id,actor_id,actor_type,resolution,final_qbo_account_id,post_after,idempotency_key,metadata
    ) VALUES (
      p_business_id,(approval->>'transaction_id')::uuid,p_actor_id,p_actor_type,
      coalesce(inflow_decision->>'resolution_type',approval#>>'{meta,user_selected_resolution}','categorize_new'),
      approval->>'final_qbo_account_id',nullif(approval->>'post_after','')::timestamptz,event_key,
      jsonb_build_object('source',coalesce(inflow_decision->>'operator_source','books_review'),
        'posting_generation',approval#>>'{meta,posting_generation}',
        'credit_card_inflow_resolution',inflow_decision,
        'statement_settlement_authority',approval#>'{meta,accounting_review_completed,statement_settlement_authority}')
    ) ON CONFLICT (business_id,idempotency_key) DO NOTHING;
  END LOOP;

  RETURN QUERY SELECT tc.* FROM public.transaction_categorizations tc
    WHERE tc.business_id=p_business_id AND tc.transaction_id IN
      (SELECT (value->>'transaction_id')::uuid FROM jsonb_array_elements(p_approvals));
END; $function$

CREATE OR REPLACE FUNCTION public.validate_credit_card_payment_pair_business()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_checking_business_id uuid;
  v_card_business_id uuid;
begin
  select business_id
    into v_checking_business_id
  from public.bank_transactions
  where id = new.checking_transaction_id;

  if v_checking_business_id is distinct from new.business_id then
    raise exception 'credit_card_payment_pair_checking_business_mismatch';
  end if;

  if new.credit_card_transaction_id is not null then
    select business_id
      into v_card_business_id
    from public.bank_transactions
    where id = new.credit_card_transaction_id;

    if v_card_business_id is distinct from new.business_id then
      raise exception 'credit_card_payment_pair_card_business_mismatch';
    end if;
  end if;

  return new;
end;
$function$

