CREATE OR REPLACE FUNCTION public.reconcile_stale_business_chat_credits(p_before timestamp with time zone DEFAULT clock_timestamp())
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE v_count integer := 0; v_row record;
BEGIN
  FOR v_row IN SELECT l.business_id, l.request_id FROM public.business_chat_credit_ledger l
    WHERE l.state = 'reserved' AND l.reservation_expires_at < p_before ORDER BY l.reservation_expires_at FOR UPDATE SKIP LOCKED
  LOOP
    PERFORM public.release_business_chat_credit(v_row.business_id, v_row.request_id, 'stale_reservation');
    v_count := v_count + 1;
  END LOOP;
  RETURN v_count;
END;
$function$

CREATE OR REPLACE FUNCTION public.confirm_selected_credit_card_payment_pair_atomic(p_business_id uuid, p_initiating_transaction_id uuid, p_opposite_transaction_id uuid, p_target_qbo_account_id text, p_expected_opposite_updated_at timestamp with time zone, p_idempotency_key text, p_actor text DEFAULT 'user'::text, p_match_method text DEFAULT 'books_review'::text, p_correlation_id text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_started timestamptz := clock_timestamp();
  v_stage timestamptz := v_started;
  v_initiating public.bank_transactions;
  v_opposite public.bank_transactions;
  v_checking public.bank_transactions;
  v_card public.bank_transactions;
  v_checking_cat public.transaction_categorizations;
  v_card_cat public.transaction_categorizations;
  v_checking_mapping public.plaid_qbo_account_mappings;
  v_card_mapping public.plaid_qbo_account_mappings;
  v_pair public.credit_card_payment_pairs;
  v_now timestamptz := now();
  v_days integer;
  v_lock_ms numeric;
  v_initiating_load_ms numeric;
  v_opposite_load_ms numeric;
  v_revalidation_ms numeric;
  v_pair_ms numeric;
  v_lifecycle_ms numeric;
  v_audit_ms numeric;
  v_idempotent boolean := false;
begin
  if p_business_id is null or p_initiating_transaction_id is null or p_opposite_transaction_id is null
     or p_initiating_transaction_id = p_opposite_transaction_id then
    raise exception 'cc_payment_pair_invalid_selected_transactions';
  end if;
  if nullif(trim(coalesce(p_idempotency_key, '')), '') is null or length(p_idempotency_key) > 200 then
    raise exception 'cc_payment_pair_invalid_idempotency_key';
  end if;

  -- Stable ordering prevents cross-confirm deadlocks and is the pair claim.
  perform 1 from public.bank_transactions
   where business_id = p_business_id
     and id in (p_initiating_transaction_id, p_opposite_transaction_id)
   order by id for update;
  v_lock_ms := extract(epoch from (clock_timestamp() - v_stage)) * 1000;
  v_stage := clock_timestamp();

  select * into v_initiating from public.bank_transactions
   where business_id=p_business_id and id=p_initiating_transaction_id;
  v_initiating_load_ms := extract(epoch from (clock_timestamp() - v_stage)) * 1000;
  v_stage := clock_timestamp();
  select * into v_opposite from public.bank_transactions
   where business_id=p_business_id and id=p_opposite_transaction_id;
  v_opposite_load_ms := extract(epoch from (clock_timestamp() - v_stage)) * 1000;
  v_stage := clock_timestamp();
  if v_initiating.id is null or v_opposite.id is null then raise exception 'cc_payment_pair_transaction_not_found'; end if;
  if p_expected_opposite_updated_at is not null and v_opposite.updated_at is distinct from p_expected_opposite_updated_at then
    raise exception 'cc_payment_pair_candidate_snapshot_stale';
  end if;
  if v_initiating.plaid_account_id = v_opposite.plaid_account_id then raise exception 'cc_payment_pair_same_account'; end if;
  if v_initiating.pending or v_opposite.pending
     or coalesce(v_initiating.is_archived,false) or coalesce(v_opposite.is_archived,false) then
    raise exception 'cc_payment_pair_transaction_ineligible';
  end if;

  if coalesce(v_initiating.signed_amount, v_initiating.amount) < 0
     and coalesce(v_opposite.signed_amount, v_opposite.amount) > 0 then
    v_checking := v_initiating; v_card := v_opposite;
  elsif coalesce(v_opposite.signed_amount, v_opposite.amount) < 0
     and coalesce(v_initiating.signed_amount, v_initiating.amount) > 0 then
    v_checking := v_opposite; v_card := v_initiating;
  else
    raise exception 'cc_payment_pair_sign_mismatch';
  end if;
  if round(abs(coalesce(v_checking.signed_amount,v_checking.amount))*100)
     <> round(abs(coalesce(v_card.signed_amount,v_card.amount))*100) then
    raise exception 'cc_payment_pair_amount_mismatch';
  end if;
  v_days := abs(v_checking.date-v_card.date);
  if v_days > 7 then raise exception 'cc_payment_pair_date_window_exceeded'; end if;

  select * into v_checking_mapping from public.plaid_qbo_account_mappings
   where business_id=p_business_id and plaid_account_id=v_checking.plaid_account_id limit 1;
  select * into v_card_mapping from public.plaid_qbo_account_mappings
   where business_id=p_business_id and plaid_account_id=v_card.plaid_account_id limit 1;
  if v_checking_mapping.qbo_account_id is null or v_card_mapping.qbo_account_id is null
     or lower(replace(coalesce(v_checking_mapping.qbo_account_type,''),' ','')) <> 'bank'
     or lower(replace(coalesce(v_card_mapping.qbo_account_type,''),' ','')) <> 'creditcard' then
    raise exception 'cc_payment_pair_account_mismatch';
  end if;
  if (p_initiating_transaction_id=v_checking.id and p_target_qbo_account_id is distinct from v_card_mapping.qbo_account_id)
     or (p_initiating_transaction_id=v_card.id and p_target_qbo_account_id is distinct from v_checking_mapping.qbo_account_id) then
    raise exception 'cc_payment_pair_target_account_mismatch';
  end if;

  select * into v_checking_cat from public.transaction_categorizations
   where business_id=p_business_id and transaction_id=v_checking.id for update;
  select * into v_card_cat from public.transaction_categorizations
   where business_id=p_business_id and transaction_id=v_card.id for update;
  if v_checking_cat.transaction_id is null or v_card_cat.transaction_id is null then raise exception 'cc_payment_pair_categorization_missing'; end if;
  if not (
       v_checking_cat.status in ('needs_review','handled','matched')
       or (
         v_checking_cat.status in ('approved','auto_approved')
         and lower(coalesce(v_checking_cat.meta ->> 'taxonomy_type','')) = 'cc_payment'
         and v_checking_cat.qbo_txn_id is null
         and v_checking_cat.posted_at is null
       )
     ) or not (
       v_card_cat.status in ('needs_review','handled','matched')
       or (
         v_card_cat.status in ('approved','auto_approved')
         and lower(coalesce(v_card_cat.meta ->> 'taxonomy_type','')) = 'cc_payment'
         and v_card_cat.qbo_txn_id is null
         and v_card_cat.posted_at is null
       )
     ) then
    raise exception 'cc_payment_pair_transaction_ineligible';
  end if;
  if v_checking_cat.qbo_txn_id is not null or v_card_cat.qbo_txn_id is not null
     or v_checking_cat.posted_at is not null or v_card_cat.posted_at is not null then raise exception 'cc_payment_pair_leg_already_posted'; end if;
  v_revalidation_ms := extract(epoch from (clock_timestamp() - v_stage)) * 1000;
  v_stage := clock_timestamp();

  select * into v_pair from public.credit_card_payment_pairs
   where business_id=p_business_id and status <> 'voided'
     and (checking_transaction_id in (v_checking.id,v_card.id)
       or credit_card_transaction_id in (v_checking.id,v_card.id))
   order by updated_at desc limit 1 for update;
  if v_pair.id is not null then
    if v_pair.checking_transaction_id <> v_checking.id or v_pair.credit_card_transaction_id <> v_card.id then
      raise exception 'cc_payment_pair_leg_already_consumed';
    end if;
    v_idempotent := v_pair.status in ('confirmed','posting','failed','posted');
    if v_idempotent and v_checking_cat.status = 'matched' and v_card_cat.status = 'matched' then
      return jsonb_build_object(
        'ok',true,'matched',true,'idempotent',true,'pair',to_jsonb(v_pair),
        'lifecycle_rows',jsonb_build_array(to_jsonb(v_checking_cat),to_jsonb(v_card_cat)),
        'correlation_id',p_correlation_id,
        'timings_ms',jsonb_build_object('lock_claim_acquisition_ms',v_lock_ms,
          'initiating_transaction_load_ms',v_initiating_load_ms,'opposite_transaction_load_ms',v_opposite_load_ms,
          'selected_candidate_revalidation_ms',v_revalidation_ms,
          'database_transaction_precommit_ms',extract(epoch from (clock_timestamp()-v_started))*1000)
      );
    end if;
    if v_pair.status = 'posted' then raise exception 'cc_payment_pair_already_posted'; end if;
    update public.credit_card_payment_pairs set status='confirmed', post_error=null, updated_at=v_now,
      idempotency_key=coalesce(idempotency_key,p_idempotency_key),
      match_evidence=coalesce(match_evidence,'{}'::jsonb)||jsonb_build_object(
        'confirmed_at',v_now,'confirmed_by',p_actor,'confirmation_source',p_match_method,'correlation_id',p_correlation_id)
     where id=v_pair.id returning * into v_pair;
  else
    insert into public.credit_card_payment_pairs (
      business_id,checking_transaction_id,credit_card_transaction_id,
      checking_plaid_account_id,credit_card_plaid_account_id,
      checking_qbo_account_id,checking_qbo_account_name,credit_card_qbo_account_id,credit_card_qbo_account_name,
      amount,payment_date,matched_date,status,match_confidence,match_evidence,request_id,idempotency_key,updated_at
    ) values (
      p_business_id,v_checking.id,v_card.id,v_checking.plaid_account_id,v_card.plaid_account_id,
      v_checking_mapping.qbo_account_id,v_checking_mapping.qbo_account_name,v_card_mapping.qbo_account_id,v_card_mapping.qbo_account_name,
      round(abs(coalesce(v_checking.signed_amount,v_checking.amount))::numeric,2),v_checking.date,v_card.date,'confirmed','high',
      jsonb_build_object('matcher','selected_pair_atomic_v1','date_window_days',7,'date_diff_days',v_days,
        'amount_minor_units',round(abs(coalesce(v_checking.signed_amount,v_checking.amount))*100),
        'qbo_mappings_verified',true,'confirmed_at',v_now,'confirmed_by',p_actor,
        'confirmation_source',p_match_method,'correlation_id',p_correlation_id),
      'bizzi_cc_'||substr(md5(p_business_id::text||'|'||v_checking.id::text||'|'||v_card.id::text),1,36),
      p_idempotency_key,v_now
    ) returning * into v_pair;
  end if;
  v_pair_ms := extract(epoch from (clock_timestamp() - v_stage))*1000;
  v_stage := clock_timestamp();

  update public.transaction_categorizations tc set
    status='matched', review_status='matched', reviewed_at=coalesce(tc.reviewed_at,v_now),
    posting_status='not_scheduled', post_after=null, post_error=null,qbo_txn_id=null,qbo_txn_type=null,posted_at=null,
    final_qbo_account_id=null,final_qbo_account_name=null,decided_by=p_actor,decided_at=v_now,updated_at=v_now,
    meta=coalesce(tc.meta,'{}'::jsonb)||jsonb_build_object(
      'taxonomy_type','cc_payment','cc_payment_pair_id',v_pair.id,
      'cc_payment_pair_role',case when tc.transaction_id=v_checking.id then 'checking' else 'credit_card' end,
      'cc_payment_pair_txn_id',case when tc.transaction_id=v_checking.id then v_card.id else v_checking.id end,
      'cc_payment_pair_status','confirmed','cc_payment_bank_qbo_account_id',v_pair.checking_qbo_account_id,
      'cc_payment_cc_qbo_account_id',v_pair.credit_card_qbo_account_id,
      'cc_payment_transfer_target_qbo_account_id',case when tc.transaction_id=v_checking.id then v_pair.credit_card_qbo_account_id else v_pair.checking_qbo_account_id end,
      'cc_payment_pair_counterpart_amount',case when tc.transaction_id=v_checking.id then v_pair.amount else -v_pair.amount end,
      'cc_payment_pair_counterpart_date',case when tc.transaction_id=v_checking.id then v_pair.matched_date else v_pair.payment_date end,
      'cc_payment_pair_confidence',v_pair.match_confidence,'cc_payment_pair_confirmed_at',v_now,
      'cc_payment_pair_confirmed_by',p_actor,'cc_payment_pair_confirmation_source',p_match_method,
      'match_type','credit_card_payment_pair','safe_to_auto_handle',false,'safe_to_auto_post',false)
   where tc.business_id=p_business_id and tc.transaction_id in (v_checking.id,v_card.id);
  v_lifecycle_ms := extract(epoch from (clock_timestamp()-v_stage))*1000;
  v_stage := clock_timestamp();

  if not v_idempotent then
    insert into public.credit_card_payment_pair_events (business_id,pair_id,transaction_id,event_type,actor,metadata)
    values
      (p_business_id,v_pair.id,v_checking.id,'confirmed',p_actor,jsonb_build_object('role','checking','method',p_match_method,'correlation_id',p_correlation_id)),
      (p_business_id,v_pair.id,v_card.id,'confirmed',p_actor,jsonb_build_object('role','credit_card','method',p_match_method,'correlation_id',p_correlation_id));
  end if;
  v_audit_ms := extract(epoch from (clock_timestamp()-v_stage))*1000;

  return jsonb_build_object(
    'ok',true,'matched',true,'idempotent',v_idempotent,'pair',to_jsonb(v_pair),
    'lifecycle_rows',(select jsonb_agg(to_jsonb(tc)) from public.transaction_categorizations tc
      where tc.business_id=p_business_id and tc.transaction_id in (v_checking.id,v_card.id)),
    'correlation_id',p_correlation_id,
    'timings_ms',jsonb_build_object('lock_claim_acquisition_ms',v_lock_ms,
      'initiating_transaction_load_ms',v_initiating_load_ms,'opposite_transaction_load_ms',v_opposite_load_ms,
      'selected_candidate_revalidation_ms',v_revalidation_ms,
      'pair_creation_or_reuse_ms',v_pair_ms,'both_lifecycle_rows_ms',v_lifecycle_ms,'audit_event_insertion_ms',v_audit_ms,
      'database_transaction_precommit_ms',extract(epoch from (clock_timestamp()-v_started))*1000)
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.apply_tax_classification_override_batch(p_business_id uuid, p_tax_year integer, p_actor_user_id uuid, p_override_source text, p_override_reason text, p_items jsonb)
 RETURNS SETOF transaction_tax_classifications
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
declare
  v_item jsonb;
  v_current public.transaction_tax_classifications%rowtype;
  v_updated public.transaction_tax_classifications%rowtype;
  v_previous_values jsonb;
  v_new_values jsonb;
  v_effective_user_override boolean;
  v_effective_cpa_override boolean;
  v_seen uuid[] := array[]::uuid[];
  v_transaction_id uuid;
  v_classification_id uuid;
  v_expected_updated_at timestamptz;
begin
  if p_business_id is null then
    raise exception 'invalid_tax_classification_override_batch: business_id is required' using errcode = '22023';
  end if;

  if p_tax_year is null or p_tax_year < 2000 or p_tax_year > 2100 then
    raise exception 'invalid_tax_classification_override_batch: tax_year must be between 2000 and 2100' using errcode = '22023';
  end if;

  if p_override_reason is null or length(trim(p_override_reason)) = 0 then
    raise exception 'invalid_tax_classification_override_batch: override_reason is required' using errcode = '22023';
  end if;

  if jsonb_typeof(p_items) is distinct from 'array' or jsonb_array_length(p_items) = 0 or jsonb_array_length(p_items) > 100 then
    raise exception 'invalid_tax_classification_override_batch: items must contain 1 through 100 selected classifications' using errcode = '22023';
  end if;

  for v_item in select value from jsonb_array_elements(p_items)
  loop
    v_transaction_id := nullif(v_item->>'transaction_id', '')::uuid;
    v_classification_id := nullif(v_item->>'classification_id', '')::uuid;
    if v_transaction_id is null or v_classification_id is null then
      raise exception 'invalid_tax_classification_override_batch: classification_id and transaction_id are required' using errcode = '22023';
    end if;
    if v_transaction_id = any(v_seen) then
      raise exception 'invalid_tax_classification_override_batch: duplicate transaction_id' using errcode = '22023';
    end if;
    v_seen := array_append(v_seen, v_transaction_id);

    if nullif(v_item->>'deductible_percent', '')::numeric < 0
       or nullif(v_item->>'deductible_percent', '')::numeric > 100 then
      raise exception 'invalid_tax_classification_override_batch: deductible_percent must be between 0 and 100' using errcode = '22023';
    end if;

    if (v_item->>'classification_status') not in ('needs_review', 'needs_tax_review', 'auto_classified', 'user_confirmed', 'cpa_confirmed', 'excluded') then
      raise exception 'invalid_tax_classification_override_batch: invalid classification_status' using errcode = '22023';
    end if;

    if (v_item->>'deductibility_status') not in (
      'fully_deductible',
      'partially_deductible',
      'nondeductible',
      'capitalizable',
      'balance_sheet',
      'needs_review',
      'not_yet_determined'
    ) then
      raise exception 'invalid_tax_classification_override_batch: invalid deductibility_status' using errcode = '22023';
    end if;

    if (v_item->>'classification_status') = 'needs_tax_review'
       and (
         v_item->>'tax_category' is distinct from 'tax_review_holding'
         or v_item->>'deductibility_status' is distinct from 'not_yet_determined'
         or nullif(v_item->>'deductible_percent', '') is not null
         or nullif(v_item->>'deductible_amount', '') is not null
       ) then
      raise exception 'invalid_tax_classification_override_batch: needs_tax_review requires tax_review_holding with null deduction fields'
        using errcode = '22023';
    end if;

    if (v_item->>'classification_status') = 'cpa_confirmed'
       and coalesce(p_override_source, '') not in ('cpa', 'admin') then
      raise exception 'invalid_tax_classification_override_batch: CPA confirmation requires CPA or admin source' using errcode = '22023';
    end if;
  end loop;

  for v_item in select value from jsonb_array_elements(p_items)
  loop
    v_transaction_id := (v_item->>'transaction_id')::uuid;
    v_expected_updated_at := nullif(v_item->>'expected_updated_at', '')::timestamptz;

    select * into v_current
    from public.transaction_tax_classifications
    where business_id = p_business_id
      and transaction_id = v_transaction_id
      and tax_year = p_tax_year
    for update;

    if not found then
      raise exception 'classification_not_found' using errcode = 'P0002';
    end if;

    if v_current.id is distinct from nullif(v_item->>'classification_id', '')::uuid then
      raise exception 'classification_conflict' using errcode = '40001';
    end if;

    if v_expected_updated_at is not null
       and v_current.updated_at is distinct from v_expected_updated_at then
      raise exception 'classification_conflict' using errcode = '40001';
    end if;

    v_effective_user_override := case
      when v_item ? 'user_override' then coalesce((v_item->>'user_override')::boolean, false) or (v_item->>'classification_status') = 'user_confirmed'
      else coalesce(v_current.user_override, false) or (v_item->>'classification_status') = 'user_confirmed'
    end;

    v_effective_cpa_override :=
      coalesce((v_item->>'cpa_override')::boolean, false)
      or coalesce(v_current.cpa_override, false)
      or (v_item->>'classification_status') = 'cpa_confirmed';

    v_previous_values := jsonb_build_object(
      'tax_category', v_current.tax_category,
      'deductibility_status', v_current.deductibility_status,
      'deductible_percent', v_current.deductible_percent,
      'book_amount', v_current.book_amount,
      'deductible_amount', v_current.deductible_amount,
      'nondeductible_amount', v_current.nondeductible_amount,
      'capitalizable_amount', v_current.capitalizable_amount,
      'tax_treatment', v_current.tax_treatment,
      'classification_status', v_current.classification_status,
      'confidence_score', v_current.confidence_score,
      'confidence_level', v_current.confidence_level,
      'source', v_current.source,
      'requires_review', v_current.requires_review,
      'reason', v_current.reason,
      'user_override', v_current.user_override,
      'cpa_override', v_current.cpa_override,
      'metadata', v_current.metadata
    );

    v_new_values := jsonb_build_object(
      'tax_category', v_item->>'tax_category',
      'deductibility_status', v_item->>'deductibility_status',
      'deductible_percent', nullif(v_item->>'deductible_percent', '')::numeric,
      'book_amount', nullif(v_item->>'book_amount', '')::numeric,
      'deductible_amount', nullif(v_item->>'deductible_amount', '')::numeric,
      'nondeductible_amount', nullif(v_item->>'nondeductible_amount', '')::numeric,
      'capitalizable_amount', nullif(v_item->>'capitalizable_amount', '')::numeric,
      'tax_treatment', coalesce(v_item->'tax_treatment', 'null'::jsonb),
      'classification_status', v_item->>'classification_status',
      'confidence_score', nullif(v_item->>'confidence_score', '')::numeric,
      'confidence_level', v_item->>'confidence_level',
      'source', v_item->>'source',
      'requires_review', (v_item->>'requires_review')::boolean,
      'reason', v_item->>'reason',
      'user_override', v_effective_user_override,
      'cpa_override', v_effective_cpa_override,
      'metadata', coalesce(v_current.metadata, '{}'::jsonb) || coalesce(v_item->'metadata', '{}'::jsonb)
    );

    insert into public.tax_classification_overrides (
      business_id, tax_year, transaction_id, classification_id, previous_values,
      new_values, override_source, override_reason, overridden_by, created_at
    )
    values (
      p_business_id, p_tax_year, v_transaction_id, v_current.id, v_previous_values,
      v_new_values, p_override_source, p_override_reason, p_actor_user_id, now()
    );

    update public.transaction_tax_classifications
    set
      tax_category = v_item->>'tax_category',
      deductibility_status = v_item->>'deductibility_status',
      deductible_percent = nullif(v_item->>'deductible_percent', '')::numeric,
      book_amount = nullif(v_item->>'book_amount', '')::numeric,
      deductible_amount = nullif(v_item->>'deductible_amount', '')::numeric,
      nondeductible_amount = nullif(v_item->>'nondeductible_amount', '')::numeric,
      capitalizable_amount = nullif(v_item->>'capitalizable_amount', '')::numeric,
      tax_treatment = coalesce(v_item->'tax_treatment', 'null'::jsonb),
      classification_status = v_item->>'classification_status',
      confidence_score = nullif(v_item->>'confidence_score', '')::numeric,
      confidence_level = v_item->>'confidence_level',
      source = v_item->>'source',
      requires_review = (v_item->>'requires_review')::boolean,
      reason = v_item->>'reason',
      user_override = v_effective_user_override,
      cpa_override = v_effective_cpa_override,
      metadata = coalesce(metadata, '{}'::jsonb) || coalesce(v_item->'metadata', '{}'::jsonb),
      updated_at = now()
    where id = v_current.id
    returning * into v_updated;

    return next v_updated;
  end loop;
end;
$function$

CREATE OR REPLACE FUNCTION public.finalize_forecast_v1_run(p_business_id uuid, p_forecast_run_id uuid, p_expected_months integer, p_months jsonb)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_run public.forecast_runs%rowtype;
  v_count integer;
  v_distinct_count integer;
  v_missing_count integer;
begin
  if p_business_id is null or p_forecast_run_id is null then
    raise exception 'forecast_finalization_missing_identity' using errcode = '22023';
  end if;

  if p_expected_months <> 12 then
    raise exception 'forecast_expected_months_invalid' using errcode = '22023';
  end if;

  if jsonb_typeof(p_months) <> 'array' then
    raise exception 'forecast_month_payload_invalid' using errcode = '22023';
  end if;

  select *
    into v_run
  from public.forecast_runs
  where id = p_forecast_run_id
    and business_id = p_business_id
  for update;

  if not found then
    raise exception 'forecast_run_not_found' using errcode = '22023';
  end if;

  if v_run.status <> 'generating' then
    raise exception 'forecast_run_not_generating' using errcode = '22023';
  end if;

  with parsed as (
    select
      (month)::date as month,
      baseline_revenue,
      baseline_expenses,
      baseline_operating_net_cash_flow,
      effective_revenue,
      effective_expenses,
      effective_operating_net_cash_flow
    from jsonb_to_recordset(p_months) as x(
      month date,
      baseline_revenue numeric,
      baseline_expenses numeric,
      baseline_operating_net_cash_flow numeric,
      effective_revenue numeric,
      effective_expenses numeric,
      effective_operating_net_cash_flow numeric
    )
  )
  select count(*), count(distinct month)
    into v_count, v_distinct_count
  from parsed;

  if v_count <> p_expected_months or v_distinct_count <> p_expected_months then
    raise exception 'forecast_month_count_invalid' using errcode = '22023';
  end if;

  with expected as (
    select generate_series(v_run.forecast_start, v_run.forecast_end, interval '1 month')::date as month
  ),
  parsed as (
    select (month)::date as month
    from jsonb_to_recordset(p_months) as x(month date)
  )
  select count(*)
    into v_missing_count
  from expected e
  left join parsed p on p.month = e.month
  where p.month is null;

  if v_missing_count <> 0 then
    raise exception 'forecast_months_not_contiguous' using errcode = '22023';
  end if;

  delete from public.forecast_months
  where forecast_run_id = p_forecast_run_id
    and business_id = p_business_id;

  insert into public.forecast_months (
    forecast_run_id,
    business_id,
    month,
    baseline_revenue,
    baseline_expenses,
    baseline_operating_net_cash_flow,
    effective_revenue,
    effective_expenses,
    effective_operating_net_cash_flow
  )
  select
    p_forecast_run_id,
    p_business_id,
    (month)::date,
    baseline_revenue,
    baseline_expenses,
    baseline_operating_net_cash_flow,
    effective_revenue,
    effective_expenses,
    effective_operating_net_cash_flow
  from jsonb_to_recordset(p_months) as x(
    month date,
    baseline_revenue numeric,
    baseline_expenses numeric,
    baseline_operating_net_cash_flow numeric,
    effective_revenue numeric,
    effective_expenses numeric,
    effective_operating_net_cash_flow numeric
  );

  select count(*)
    into v_count
  from public.forecast_months
  where forecast_run_id = p_forecast_run_id
    and business_id = p_business_id;

  if v_count <> p_expected_months then
    raise exception 'forecast_month_persistence_verification_failed' using errcode = '22023';
  end if;

  update public.forecast_runs
  set status = 'completed',
      generated_at = timezone('utc'::text, now()),
      generation_lease_expires_at = null,
      error_metadata = '{}'::jsonb,
      updated_at = timezone('utc'::text, now())
  where id = p_forecast_run_id
    and business_id = p_business_id;

  return p_forecast_run_id;
end;
$function$

CREATE OR REPLACE FUNCTION public.claim_credit_card_payment_pair_posting(p_business_id uuid, p_pair_id uuid, p_request_id text, p_idempotency_key text, p_now timestamp with time zone DEFAULT now(), p_lease_seconds integer DEFAULT 600)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_row public.credit_card_payment_pairs;
begin
  if p_business_id is null or p_pair_id is null then
    raise exception 'missing_cc_payment_pair_identity';
  end if;
  if p_request_id is null or length(trim(p_request_id)) = 0 or length(p_request_id) > 50 then
    raise exception 'invalid_cc_payment_pair_request_id';
  end if;

  select *
    into v_row
  from public.credit_card_payment_pairs
  where business_id = p_business_id
    and id = p_pair_id
  for update;

  if not found then
    raise exception 'cc_payment_pair_not_found';
  end if;

  if v_row.status = 'posted' and v_row.qbo_txn_id is not null then
    return jsonb_build_object('claimed', false, 'already_posted', true, 'pair', to_jsonb(v_row));
  end if;

  if v_row.status = 'posting'
     and v_row.lease_expires_at is not null
     and v_row.lease_expires_at > p_now
     and coalesce(v_row.request_id, p_request_id) = p_request_id then
    return jsonb_build_object('claimed', false, 'already_posted', false, 'pair', to_jsonb(v_row));
  end if;

  update public.credit_card_payment_pairs
     set status = 'posting',
         request_id = coalesce(request_id, p_request_id),
         idempotency_key = coalesce(idempotency_key, p_idempotency_key),
         posting_started_at = p_now,
         lease_expires_at = p_now + make_interval(secs => greatest(coalesce(p_lease_seconds, 600), 1)),
         last_post_attempt_at = p_now,
         updated_at = p_now
   where business_id = p_business_id
     and id = p_pair_id
     and (request_id is null or request_id = p_request_id)
  returning * into v_row;

  if not found then
    raise exception 'cc_payment_pair_request_id_mismatch';
  end if;

  return jsonb_build_object('claimed', true, 'already_posted', false, 'pair', to_jsonb(v_row));
end;
$function$

CREATE OR REPLACE FUNCTION public.confirm_pending_transaction_settled(p_business_id uuid, p_transaction_id uuid, p_actor_user_id uuid, p_actor_label text, p_statement_date date, p_statement_amount numeric, p_reason text, p_idempotency_key text, p_decision_version integer DEFAULT 1)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_bank public.bank_transactions%rowtype; v_cat public.transaction_categorizations%rowtype; v_now timestamptz:=now(); v_existing jsonb; v_before jsonb; v_replacement jsonb; v_candidates jsonb; v_provenance text;
begin
  select * into v_bank from public.bank_transactions where business_id=p_business_id and id=p_transaction_id for update;
  if not found then raise exception 'transaction_not_found'; end if;
  select * into v_cat from public.transaction_categorizations where business_id=p_business_id and transaction_id=p_transaction_id for update;
  if v_bank.pending is not true and v_bank.pending_resolution_state <> 'promoted_to_settled' then raise exception 'transaction_not_pending'; end if;
  if v_cat.qbo_txn_id is not null or v_cat.posted_at is not null or v_cat.reconciled_at is not null or v_cat.status in ('posted','matched','matched_existing_qbo') then raise exception 'transaction_already_accounted'; end if;
  if v_cat.posting_status='posting' or coalesce((v_cat.meta->>'posting_in_progress')::boolean,false) then raise exception 'posting_in_progress'; end if;
  if p_actor_user_id is null then raise exception 'operator_authorization_required'; end if;
  if p_statement_date is null then raise exception 'invalid_statement_date'; end if;
  if p_statement_amount is null or p_statement_amount=0 then raise exception 'invalid_statement_amount'; end if;
  if round(abs(p_statement_amount)::numeric,2) <> round(abs(v_bank.amount)::numeric,2) then raise exception 'statement_amount_mismatch'; end if;
  if exists (select 1 from public.bank_transactions r where r.business_id=p_business_id and r.is_archived=false and r.pending is not true and r.pending_transaction_id=v_bank.plaid_transaction_id and r.id<>v_bank.id) then raise exception 'posted_replacement_exists'; end if;
  select jsonb_build_object('state',resulting_state,'created_at',created_at) into v_existing from public.pending_transaction_resolution_events where business_id=p_business_id and idempotency_key=p_idempotency_key;
  if v_existing is not null then return v_existing || jsonb_build_object('idempotent',true); end if;
  v_before:=jsonb_build_object('pending',v_bank.pending,'pending_resolution_state',v_bank.pending_resolution_state,'accounting_review_required',v_bank.accounting_review_required,'accounting_review_reason',v_bank.accounting_review_reason);
  v_provenance:=case when coalesce((v_bank.raw->>'recovery_imported')::boolean,false) or v_bank.raw->>'plaid_recovery_batch_id' is not null then 'replacement_card_recovery' else coalesce(v_bank.raw->>'canonical_source','normal_sync') end;
  select to_jsonb(r) into v_replacement from public.bank_transactions r where r.business_id=p_business_id and r.is_archived=false and r.pending is not true and r.pending_transaction_id=v_bank.plaid_transaction_id and r.id<>v_bank.id limit 1;
  v_candidates:=coalesce(v_cat.meta->'qbo_duplicate_candidates','[]'::jsonb);
  update public.bank_transactions set pending=false, pending_resolution_state='promoted_to_settled', pending_resolved_at=v_now,
    pending_resolved_by=p_actor_user_id, pending_resolution_payload=jsonb_build_object(
      'original_pending',true,'original_plaid_transaction_id',v_bank.plaid_transaction_id,'original_pending_transaction_id',v_bank.pending_transaction_id,
      'statement_confirmed_date',p_statement_date,'statement_confirmed_amount',p_statement_amount,'operator_note',nullif(trim(p_reason),''),
      'decision_version',p_decision_version,'confirmed_at',v_now,'confirmed_by',p_actor_user_id,'confirmed_by_email',p_actor_label,
      'request_id',p_idempotency_key,'provider_provenance',v_provenance,'provider_last_update',coalesce(v_bank.last_seen_at,v_bank.updated_at),
      'posted_replacement_search',jsonb_build_object('found',v_replacement is not null,'result',v_replacement),
      'qbo_candidate_search',jsonb_build_object('found',jsonb_array_length(v_candidates)>0,'result',v_candidates)
    ), accounting_review_required=true, accounting_review_reason='operator_confirmed_settlement'
    where business_id=p_business_id and id=p_transaction_id;
  insert into public.transaction_categorizations (business_id,transaction_id,status,review_status,posting_status,meta,post_after,updated_at)
    values (p_business_id,p_transaction_id,'needs_review','needs_review','not_scheduled',jsonb_build_object('pending_resolution_state','promoted_to_settled','operator_settlement_confirmation',jsonb_build_object('actor_user_id',p_actor_user_id,'actor_email',p_actor_label,'statement_date',p_statement_date,'statement_amount',p_statement_amount,'operator_note',nullif(trim(p_reason),''),'request_id',p_idempotency_key,'decision_version',p_decision_version,'confirmed_at',v_now)),null,v_now)
    on conflict (business_id,transaction_id) do update set status='needs_review',review_status='needs_review',posting_status='not_scheduled',post_after=null,
      meta=coalesce(public.transaction_categorizations.meta,'{}'::jsonb)||excluded.meta,updated_at=v_now;
  insert into public.pending_transaction_resolution_events (business_id,transaction_id,action,prior_state,resulting_state,actor_user_id,actor_label,reason,evidence,idempotency_key)
    values (p_business_id,p_transaction_id,'confirm_settled_from_statement',coalesce(v_bank.pending_resolution_state,'stale_pending_check_required'),'promoted_to_settled',p_actor_user_id,p_actor_label,p_reason,
      jsonb_build_object('actor_user_id',p_actor_user_id,'actor_email',p_actor_label,'decision_timestamp',v_now,'action_type','confirm_settled_from_statement',
        'statement_date',p_statement_date,'statement_amount',p_statement_amount,'operator_note',nullif(trim(p_reason),''),
        'before_state',v_before,'after_state',jsonb_build_object('pending',false,'pending_resolution_state','promoted_to_settled','accounting_review_required',true,'accounting_review_reason','operator_confirmed_settlement','categorization_status','needs_review','posting_status','not_scheduled'),
        'provider_provenance',v_provenance,'provider_last_update',coalesce(v_bank.last_seen_at,v_bank.updated_at),
        'posted_replacement_search',jsonb_build_object('found',v_replacement is not null,'result',v_replacement),
        'qbo_candidate_search',jsonb_build_object('found',jsonb_array_length(v_candidates)>0,'result',v_candidates),
        'business_id',p_business_id,'transaction_id',p_transaction_id,'request_id',p_idempotency_key,'idempotency_key',p_idempotency_key,
        'provider_write',false,'qbo_write',false,'decision_version',p_decision_version),p_idempotency_key);
  return jsonb_build_object('idempotent',false,'state','promoted_to_settled','transaction_id',p_transaction_id);
end $function$

CREATE OR REPLACE FUNCTION public.claim_bank_qbo_match(p_business_id uuid, p_bank_transaction_id uuid, p_match_id uuid, p_item_id uuid, p_confirmed_at timestamp with time zone, p_actor_role text, p_meta jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_item public.bank_qbo_match_items%rowtype;
begin
  select * into v_item
  from public.bank_qbo_match_items
  where id = p_item_id and match_id = p_match_id and business_id = p_business_id
  for update;

  if not found then raise exception using errcode = 'P0002', message = 'primary_match_item_missing'; end if;
  if v_item.qbo_realm_id is null then raise exception using errcode = '23502', message = 'qbo_match_realm_required'; end if;

  update public.bank_qbo_match_items
  set active_confirmed = false
  where business_id = p_business_id and match_id = p_match_id;

  begin
    update public.bank_qbo_match_items set active_confirmed = true where id = v_item.id;
  exception when unique_violation then
    raise exception using errcode = '23505', message = 'qbo_entity_already_matched';
  end;

  update public.bank_qbo_matches
  set status = 'confirmed', confirmed_at = p_confirmed_at, updated_at = p_confirmed_at,
      actor_role = p_actor_role, meta = p_meta
  where id = p_match_id and business_id = p_business_id
    and bank_transaction_id = p_bank_transaction_id
    and status in ('needs_confirmation','ambiguous');

  if not found then raise exception using errcode = 'P0001', message = 'match_not_confirmable'; end if;
  return jsonb_build_object('ok', true, 'match_id', p_match_id, 'item_id', v_item.id);
end;
$function$

CREATE OR REPLACE FUNCTION public.undo_credit_card_payment_pair_atomic(p_business_id uuid, p_pair_id uuid, p_actor text DEFAULT 'user'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_pair public.credit_card_payment_pairs;
  v_now timestamptz := now();
  v_ids uuid[];
begin
  select * into v_pair from public.credit_card_payment_pairs
   where business_id = p_business_id and id = p_pair_id for update;
  if not found then raise exception 'cc_payment_pair_not_found'; end if;
  if v_pair.status = 'voided' then
    return jsonb_build_object('ok',true,'undone',true,'idempotent',true,'pair_id',v_pair.id,'transaction_ids','[]'::jsonb);
  end if;
  if v_pair.status = 'posted' or v_pair.qbo_txn_id is not null or v_pair.posted_at is not null then
    raise exception 'cc_payment_pair_already_posted';
  end if;

  v_ids := array[v_pair.checking_transaction_id, v_pair.credit_card_transaction_id];
  perform 1 from public.bank_transactions where business_id = p_business_id and id = any(v_ids) for update;
  perform 1 from public.transaction_categorizations where business_id = p_business_id and transaction_id = any(v_ids) for update;

  update public.credit_card_payment_pairs
     set status='voided', post_error='cc_payment_pair_undone_by_user',
         posting_started_at=null, lease_expires_at=null, updated_at=v_now
   where id=v_pair.id;

  update public.transaction_categorizations
     set status='needs_review', review_status='needs_review', posting_status='not_scheduled',
         post_after=null, post_error=null, last_post_attempt_at=null,
         qbo_txn_id=null, qbo_txn_type=null, posted_at=null, reconciled_at=null,
         suggested_qbo_account_id=null, suggested_qbo_account_name=null,
         suggested_canonical_account_key=null, final_qbo_account_id=null,
         final_qbo_account_name=null, final_canonical_account_key=null,
         decided_by=p_actor, decided_at=v_now, updated_at=v_now,
         meta = (coalesce(meta,'{}'::jsonb) - array[
           'cc_payment_pair_id','cc_payment_pair_role','cc_payment_pair_txn_id',
           'cc_payment_pair_plaid_account_id','cc_payment_pair_status',
           'cc_payment_pair_confidence','cc_payment_pair_ambiguous','cc_payment_pair_candidates',
           'cc_payment_pair_confirmed_at','cc_payment_pair_confirmed_by',
           'cc_payment_pair_confirmation_source','match_type','auto_approve_reason',
           'auto_handled_reason','auto_handle_decision','posting_in_progress',
           'next_post_attempt_at','cc_payment_bank_qbo_account_id','cc_payment_bank_qbo_account_name',
           'cc_payment_cc_qbo_account_id','cc_payment_cc_qbo_account_name',
           'cc_payment_transfer_target_qbo_account_id','cc_payment_transfer_target_qbo_account_name'
         ]) || jsonb_build_object(
           'taxonomy_type','cc_payment','taxonomy_subtype','credit_card_payment',
           'post_block_reason','cc_payment_pair_requires_confirmation',
           'cc_payment_mapping_confidence','manual_review',
           'cc_payment_mapping_notes','voided_pair_requires_rematch',
           'safe_to_auto_handle',false,'safe_to_auto_post',false,
           'review_reopen_authorized',true,
           'review_reopen_reason','credit_card_payment_pair_undone_by_user'
         )
   where business_id=p_business_id and transaction_id=any(v_ids);

  insert into public.credit_card_payment_pair_events
    (business_id,pair_id,transaction_id,event_type,actor,metadata)
  select p_business_id,v_pair.id,unnest(v_ids),'undone',p_actor,'{}'::jsonb;

  return jsonb_build_object('ok',true,'undone',true,'idempotent',false,'pair_id',v_pair.id,
    'transaction_ids',to_jsonb(v_ids));
end;
$function$

CREATE OR REPLACE FUNCTION public.exclude_bookkeeping_transaction(p_business_id uuid, p_transaction_id uuid, p_actor text, p_reason text DEFAULT NULL::text, p_source text DEFAULT 'books_review'::text, p_correlation_id text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_bank public.bank_transactions%rowtype;
  v_cat public.transaction_categorizations%rowtype;
  v_prior text;
  v_now timestamptz := now();
  v_meta jsonb;
begin
  select * into v_bank from public.bank_transactions
   where business_id = p_business_id and id = p_transaction_id and is_archived is false
   for update;
  if not found then raise exception 'transaction_not_found'; end if;

  insert into public.bookkeeping_exclusion_events (
    business_id, transaction_id, connected_account_id, event_type, actor, reason, correlation_id
  ) values (p_business_id, p_transaction_id, v_bank.plaid_account_id, 'exclusion_requested', p_actor, p_reason, p_correlation_id);

  select * into v_cat from public.transaction_categorizations
   where business_id = p_business_id and transaction_id = p_transaction_id
   for update;

  if v_cat.status = 'excluded' and v_cat.excluded_at is not null then
    return jsonb_build_object('idempotent', true, 'primary_feed', 'excluded', 'excluded_at', v_cat.excluded_at);
  end if;

  if v_cat.qbo_txn_id is not null or v_cat.posted_at is not null or v_cat.status = 'posted' then
    insert into public.bookkeeping_exclusion_events (business_id,transaction_id,connected_account_id,event_type,actor,prior_lifecycle,resulting_lifecycle,reason,correlation_id)
    values (p_business_id,p_transaction_id,v_bank.plaid_account_id,'exclusion_rejected_concurrent_processing',p_actor,'posted','posted','authoritative_qbo_receipt',p_correlation_id);
    raise exception 'transaction_already_posted';
  end if;
  if coalesce((v_cat.meta ->> 'posting_in_progress')::boolean, false) or v_cat.posting_status = 'posting' then
    insert into public.bookkeeping_exclusion_events (business_id,transaction_id,connected_account_id,event_type,actor,prior_lifecycle,resulting_lifecycle,reason,correlation_id)
    values (p_business_id,p_transaction_id,v_bank.plaid_account_id,'exclusion_rejected_concurrent_processing',p_actor,v_cat.status,v_cat.status,'posting_in_progress',p_correlation_id);
    raise exception 'posting_in_progress';
  end if;
  if v_cat.status in ('matched','matched_existing_qbo')
     or v_cat.meta ->> 'incoming_deposit_match_status' = 'confirmed'
     or (v_cat.meta ->> 'cc_payment_pair_id' is not null and v_cat.meta ->> 'cc_payment_pair_status' in ('confirmed','matched','posted')) then
    raise exception 'transaction_already_matched';
  end if;

  v_prior := case when v_bank.pending then 'pending' else coalesce(v_cat.status, 'needs_review') end;
  v_meta := coalesce(v_cat.meta, '{}'::jsonb) || jsonb_build_object(
    'excluded_at', v_now, 'excluded_by', p_actor, 'exclusion_reason', p_reason,
    'exclusion_source', p_source, 'pre_exclusion_lifecycle', v_prior,
    'exclusion_correlation_id', p_correlation_id,
    'exclusion_snapshot', jsonb_build_object('pending',v_bank.pending,'amount',v_bank.amount,'date',v_bank.date,'memo',v_bank.name,'provider_transaction_id',v_bank.plaid_transaction_id,'prior_status',v_cat.status,'prior_posting_status',v_cat.posting_status)
  );

  insert into public.transaction_categorizations (
    business_id, transaction_id, status, review_status, posting_status, meta,
    excluded_at, excluded_by, exclusion_reason, exclusion_source,
    pre_exclusion_lifecycle, exclusion_version, exclusion_snapshot,
    post_after, updated_at
  ) values (
    p_business_id, p_transaction_id, 'excluded', 'handled', 'not_scheduled', v_meta,
    v_now, p_actor, p_reason, p_source, v_prior, 1,
    jsonb_build_object('pending',v_bank.pending,'amount',v_bank.amount,'date',v_bank.date,'memo',v_bank.name,'provider_transaction_id',v_bank.plaid_transaction_id,'prior_status',v_cat.status,'prior_posting_status',v_cat.posting_status),
    null, v_now
  ) on conflict (business_id, transaction_id) do update set
    status='excluded', review_status='handled', posting_status='not_scheduled', meta=excluded.meta,
    excluded_at=excluded.excluded_at, excluded_by=excluded.excluded_by,
    exclusion_reason=excluded.exclusion_reason, exclusion_source=excluded.exclusion_source,
    pre_exclusion_lifecycle=excluded.pre_exclusion_lifecycle,
    exclusion_version=public.transaction_categorizations.exclusion_version + 1,
    exclusion_snapshot=excluded.exclusion_snapshot, post_after=null, updated_at=v_now;

  insert into public.bookkeeping_exclusion_events (business_id,transaction_id,connected_account_id,event_type,actor,prior_lifecycle,resulting_lifecycle,reason,correlation_id)
  values (p_business_id,p_transaction_id,v_bank.plaid_account_id,'exclusion_completed',p_actor,v_prior,'excluded',p_reason,p_correlation_id);
  return jsonb_build_object('idempotent',false,'primary_feed','excluded','excluded_at',v_now,'previous_feed',v_prior);
end;
$function$

CREATE OR REPLACE FUNCTION public.prevent_stale_stripe_entitlement_update()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public'
AS $function$
begin
  if new.stripe_event_created_at_live is not null
     and old.stripe_event_created_at_live is not null
     and new.stripe_event_created_at_live < old.stripe_event_created_at_live then
    new.stripe_customer_id_live := old.stripe_customer_id_live;
    new.stripe_subscription_id_live := old.stripe_subscription_id_live;
    new.subscription_status_live := old.subscription_status_live;
    new.plan_price_id_live := old.plan_price_id_live;
    new.current_period_end_live := old.current_period_end_live;
    new.trial_end_live := old.trial_end_live;
    new.cancel_at_period_end_live := old.cancel_at_period_end_live;
    new.last_invoice_status_live := old.last_invoice_status_live;
    new.canceled_at_live := old.canceled_at_live;
    new.last_invoice_id_live := old.last_invoice_id_live;
    new.last_payment_failed_at_live := old.last_payment_failed_at_live;
    new.plan_type_live := old.plan_type_live;
    new.stripe_event_created_at_live := old.stripe_event_created_at_live;
    new.stripe_event_id_live := old.stripe_event_id_live;
  end if;
  if new.stripe_event_created_at_test is not null
     and old.stripe_event_created_at_test is not null
     and new.stripe_event_created_at_test < old.stripe_event_created_at_test then
    new.stripe_customer_id_test := old.stripe_customer_id_test;
    new.stripe_subscription_id_test := old.stripe_subscription_id_test;
    new.subscription_status_test := old.subscription_status_test;
    new.plan_price_id_test := old.plan_price_id_test;
    new.current_period_end_test := old.current_period_end_test;
    new.trial_end_test := old.trial_end_test;
    new.cancel_at_period_end_test := old.cancel_at_period_end_test;
    new.last_invoice_status_test := old.last_invoice_status_test;
    new.canceled_at_test := old.canceled_at_test;
    new.last_invoice_id_test := old.last_invoice_id_test;
    new.last_payment_failed_at_test := old.last_payment_failed_at_test;
    new.plan_type_test := old.plan_type_test;
    new.stripe_event_created_at_test := old.stripe_event_created_at_test;
    new.stripe_event_id_test := old.stripe_event_id_test;
  end if;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.restore_bookkeeping_transaction(p_business_id uuid, p_transaction_id uuid, p_actor text, p_source text DEFAULT 'books_review'::text, p_correlation_id text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_bank public.bank_transactions%rowtype;
  v_cat public.transaction_categorizations%rowtype;
  v_destination text;
  v_status text;
  v_meta jsonb;
begin
  select * into v_bank from public.bank_transactions where business_id=p_business_id and id=p_transaction_id and is_archived is false for update;
  if not found then raise exception 'transaction_not_found'; end if;
  select * into v_cat from public.transaction_categorizations where business_id=p_business_id and transaction_id=p_transaction_id for update;
  if not found or v_cat.excluded_at is null then
    return jsonb_build_object('idempotent',true,'primary_feed',case when v_bank.pending then 'pending' else 'needs_review' end);
  end if;

  v_destination := case
    when v_bank.pending then 'pending'
    when v_cat.qbo_txn_id is not null or v_cat.posted_at is not null then 'posted'
    when v_cat.meta ->> 'incoming_deposit_match_status'='confirmed' then 'matched'
    when v_cat.pre_exclusion_lifecycle in ('approved','auto_approved','handled','failed') and v_cat.final_qbo_account_id is not null then 'handled'
    else 'needs_review' end;
  v_status := case v_destination when 'posted' then 'posted' when 'matched' then 'matched_existing_qbo' when 'handled' then coalesce(nullif(v_cat.exclusion_snapshot->>'prior_status',''),'approved') else 'needs_review' end;
  v_meta := coalesce(v_cat.meta,'{}'::jsonb) - 'excluded_at' - 'excluded_by' - 'exclusion_reason' - 'exclusion_source' - 'pre_exclusion_lifecycle' - 'exclusion_correlation_id';

  update public.transaction_categorizations set status=v_status,
    review_status=case when v_destination in ('handled','posted','matched') then 'handled' else 'needs_review' end,
    posting_status=case when v_destination='posted' then 'posted' else 'not_scheduled' end,
    meta=v_meta, excluded_at=null, excluded_by=null, exclusion_reason=null,
    exclusion_source=null, pre_exclusion_lifecycle=null, post_after=null, updated_at=now()
  where business_id=p_business_id and transaction_id=p_transaction_id;

  insert into public.bookkeeping_exclusion_events (business_id,transaction_id,connected_account_id,event_type,actor,prior_lifecycle,resulting_lifecycle,reason,correlation_id)
  values (p_business_id,p_transaction_id,v_bank.plaid_account_id,'restored',p_actor,'excluded',v_destination,p_source,p_correlation_id);
  return jsonb_build_object('idempotent',false,'primary_feed',v_destination);
end;
$function$

CREATE OR REPLACE FUNCTION public.prevent_uncontrolled_qbo_realm_change()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public'
AS $function$
begin
  if old.realm_id is not null and new.realm_id is distinct from old.realm_id then
    raise exception 'QBO_COMPANY_REPLACEMENT_REQUIRES_CONTROLLED_SUPPORT_WORKFLOW'
